<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Category;use Illuminate\Http\Request;use Illuminate\Support\Str;
class CategoryController extends Controller{public function index(){return view('admin.categories.index',['categories'=>Category::latest()->paginate(15)]);}public function store(Request $r){$d=$r->validate(['name'=>'required|max:100','icon'=>'nullable|max:10','description'=>'nullable|max:1000']);$d['slug']=Str::slug($d['name']);Category::create($d);return back()->with('success','Category created.');}public function update(Request $r,Category $category){$d=$r->validate(['name'=>'required|max:100','icon'=>'nullable|max:10','description'=>'nullable|max:1000','is_active'=>'nullable|boolean']);$d['slug']=Str::slug($d['name']);$category->update($d);return back()->with('success','Category updated.');}public function destroy(Category $category){if($category->services()->exists())return back()->with('error','Delete its services first.');$category->delete();return back()->with('success','Category deleted.');}}
